import { signal } from '@pyreon/reactivity'
import { For } from '@pyreon/core'

export function App() {
  const count = signal(0)
  const items = signal([{ id: 1, t: 'a' }])
  return (
    <div>
      <button onClick={() => count(count() + 1)}>{count()}</button>
      <For each={items} key={(i) => i.id}>{(i) => <li>{i.t}</li>}</For>
    </div>
  )
}
